INSERT INTO "classifications" VALUES(3088,'claude-haiku-5-5','2026-10-25T04:07:29Z',1,0.9,0,'{"areas": ["forecasting"], "confidence": 0.9, "countries": [], "event_date": "2026-10-24", "institutions": [{"country": null, "name": "Google DeepMind", "short_name": "DeepMind", "type": "private_sector"}], "language": "es", "news_type": "other", "original_title": "La IA ya está cambiando la predicción del tiempo: con el huracán Isaías acertó su trayectoria cuando los modelos tradicionales fallaron", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A Xataka article reports that a machine-learning weather model from Google DeepMind correctly forecast the track of Hurricane Isaias when traditional numerical models failed, as shared by a user on X. The piece frames machine learning models as now operating in real time to support meteorologists.", "summary_original": "Un artículo de Xataka informa de que un modelo meteorológico de machine learning de Google DeepMind acertó la trayectoria del huracán Isaías cuando fallaron los modelos tradicionales, según compartió un usuario en X. El texto señala que estos modelos ya operan en tiempo real para apoyar a los meteorólogos.", "system_name": "DeepMind weather model (hurricane track model)", "techniques": ["ml_dl", "ai_weather_model"], "title_en": "AI is already changing weather forecasting: with Hurricane Isaias it got the track right when traditional models failed", "value_added": "Correctly predicted the track of Hurricane Isaias when traditional physics-based models failed.", "value_types": ["accuracy"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(3173,'claude-haiku-5-5','2026-10-26T04:10:27Z',0,0.9,0,'{"areas": ["hydrology", "warnings"], "confidence": 0.9, "countries": ["NP"], "event_date": "2026-10-26", "institutions": [{"country": "NP", "name": "Centre for Hydrology and Water Resources Research", "short_name": null, "type": "other_national_agency"}], "language": "en", "news_type": "policy_guidance", "original_title": "Nepal to expand flood warnings, lower glacial lake levels", "primary_area": "hydrology", "relevant": false, "review": false, "summary_en": "Nepal plans to expand flood early warning systems across six major river basins and lower water levels in four high-risk glacial lakes. The Centre for Hydrology and Water Resources Research will provide round-the-clock flood forecasting from mid-May to mid-October. The snippet does not mention any artificial intelligence or machine learning component.", "summary_original": null, "system_name": null, "techniques": [], "title_en": "Nepal to expand flood warnings, lower glacial lake levels", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3251,'claude-haiku-5-5','2026-10-26T04:10:18Z',0,0.97,0,'{"areas": ["warnings"], "confidence": 0.97, "countries": ["JP"], "event_date": "2026-10-26", "institutions": [{"country": "JP", "name": "Japan Meteorological Agency", "short_name": "JMA", "type": "NMHS"}], "language": "ja", "news_type": "other", "original_title": "台風30号は温帯低気圧に 気象庁が西日本から東日本に土砂災害など警戒呼びかけ 落雷や突風にも注意 気象庁 - ライブドアニュース", "primary_area": "warnings", "relevant": false, "review": false, "summary_en": "The Japan Meteorological Agency issued an explanatory information bulletin stating that Typhoon No. 30 has transitioned into an extratropical cyclone, warning of gales in northern Kyushu and of landslides, flooding and river rises from western to eastern Japan. The item contains no mention of artificial intelligence.", "summary_original": "気象庁は26日、台風30号から変わった温帯低気圧に関する気象解説情報を発表し、九州北部で暴風、西日本から東日本で土砂災害や浸水、河川増水への警戒を呼びかけた。24時間降水量は四国地方で180ミリと予想されるとしている。", "system_name": null, "techniques": [], "title_en": "Typhoon No. 30 becomes an extratropical cyclone; Japan Meteorological Agency calls for caution over landslides and flooding from western to eastern Japan, and warns of lightning and gusts", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3252,'claude-haiku-5-5','2026-10-26T04:10:21Z',0,0.9,0,'{"areas": ["climate_services"], "confidence": 0.9, "countries": ["JP"], "event_date": "2026-10-26", "institutions": [{"country": "JP", "name": "Japan Meteorological Agency Meteorological Research Institute", "short_name": "MRI-JMA", "type": "NMHS"}], "language": "ja", "news_type": "other", "original_title": "夏以降の大雨 温暖化で雨量2割増加か 千葉豪雨など気象庁解析", "primary_area": "climate_services", "relevant": false, "review": false, "summary_en": "The Meteorological Research Institute of the Japan Meteorological Agency reported an attribution analysis finding that record heavy rain in August and September 2026, including the Chiba heavy rain and Typhoon No. 25, was likely about 20% stronger due to global warming. The item does not mention any use of artificial intelligence.", "summary_original": "気象庁気象研究所は、今年8月から9月の記録的な大雨（千葉豪雨や台風25号など）について、地球温暖化により雨量が約2割増加した可能性が高いとする解析結果を発表した。", "system_name": null, "techniques": [], "title_en": "Heavy rain since summer may be 20% stronger due to global warming, JMA analysis shows, including Chiba heavy rain", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3253,'claude-haiku-5-5','2026-10-26T04:10:24Z',1,0.85,0,'{"areas": ["forecasting", "guidance"], "confidence": 0.85, "countries": ["JP"], "event_date": "2026-10-20", "institutions": [{"country": "JP", "name": "Japan Meteorological Agency", "short_name": "JMA", "type": "NMHS"}], "language": "ja", "news_type": "other", "original_title": "台風30号の進路予想で試される従来予想モデルとAIの実力 欧米ではすでにAI予想も 日本は未導入 (2026年10月20日掲載) - ライブドアニュース", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A news article compares conventional typhoon track forecast models with AI-based forecasts from Europe and the US in the context of Typhoon No. 30. It reports that the Japan Meteorological Agency has not yet introduced AI into its operational forecasting.", "summary_original": "台風30号の進路予想をめぐり、従来モデルと欧米のAI予想が比較されている。記事によると、気象庁はAIを予報に未導入である。", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Traditional and AI forecast models tested on Typhoon No. 30 track forecasts; AI forecasts already used in Europe and the US, Japan has not yet introduced them", "value_added": "Comparison of AI and conventional models for typhoon track forecasting; AI forecasts are reported as already used in Europe and the US but not yet in Japan''s operational forecasts.", "value_types": ["accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3254,'claude-haiku-5-5','2026-10-26T04:10:30Z',1,0.85,0,'{"areas": ["forecasting"], "confidence": 0.85, "countries": ["JP"], "event_date": "2026-10-21", "institutions": [{"country": "JP", "name": "Japan Meteorological Corporation (tenki.jp)", "short_name": "tenki.jp", "type": "private_sector"}], "language": "ja", "news_type": "other", "original_title": "台風30号の進路予想で試される従来予想モデルとAIの実力 欧米ではすでにAI予想も 日本は未導入(放送局のニュース ) - 日本気象協会 tenki.jp", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A news report notes that European and US meteorological agencies already operate AI-based weather forecasting models, and that for a 2026 typhoon approaching Japan, AI track forecasts were rated comparatively better than conventional models. Japan has not yet introduced AI forecasting into operations, according to the report.", "summary_original": "欧米の気象機関はAIを使った気象予報モデルを運用しており、2026年に日本に来た台風の予想進路では従来モデルよりAIの方が比較的好成績との評価がある。日本はまだAI予報を導入していないと報じられている。", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Traditional forecast models vs. AI in predicting the path of Typhoon No. 30; European and US agencies already run AI forecasts, Japan has not yet introduced them (broadcast news)", "value_added": "AI forecast models were reported to perform comparatively better than conventional models for the predicted track of a typhoon that approached Japan in 2026.", "value_types": ["accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3263,'claude-haiku-5-5','2026-10-26T04:10:33Z',1,0.93,0,'{"areas": ["forecasting"], "confidence": 0.93, "countries": [], "event_date": "2026-10-26", "institutions": [{"country": null, "name": "Google DeepMind", "short_name": "Google DeepMind", "type": "private_sector"}], "language": "es", "news_type": "pilot_research", "original_title": "La inteligencia artificial logró predecir la trayectoria de un huracán mejor que los modelos tradicionales: así está cambiando la meteorología", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "An AI model from Google DeepMind reportedly predicted where Hurricane Isaias would make landfall more accurately than traditional models, with timing errors of only a few hours three days before impact. The item highlights AI''s growing role in tropical cyclone track forecasting.", "summary_original": "Un modelo de inteligencia artificial de Google DeepMind anticipó con notable precisión dónde tocaría tierra el huracán Isaías, con un margen de error de pocas horas cuando faltaban tres días.", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Artificial intelligence managed to predict a hurricane''s trajectory better than traditional models: this is how meteorology is changing", "value_added": "Anticipated the landfall location and timing of Hurricane Isaias with a margin of error of a few hours three days ahead, outperforming traditional models as stated in the article.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
