INSERT INTO "classifications" VALUES(4244,'claude-haiku-5-5','2026-10-30T04:08:51Z',1,0.8,0,'{"areas": ["hydrology", "warnings"], "confidence": 0.8, "countries": ["ZA"], "event_date": "2026-10-29", "institutions": [{"country": "ZA", "name": "eThekwini Municipality research team (university-affiliated researchers)", "short_name": null, "type": "research"}], "language": "en", "news_type": "pilot_research", "original_title": "Using machine learning to build safer cities", "primary_area": "warnings", "relevant": true, "review": false, "summary_en": "Researchers in eThekwini used machine learning and satellite data to map landslide susceptibility, published in Scientific Reports. The study finds urban development, road construction, property development and vegetation loss are increasing landslide susceptibility in parts of the city. The work supports disaster risk reduction and safer urban planning.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "Using machine learning to build safer cities", "value_added": "Identifies the most landslide-prone zones in the city using machine learning and satellite data to inform hazard risk assessment.", "value_types": ["accuracy", "coverage"], "wmo_regions": ["I"]}');
INSERT INTO "classifications" VALUES(4424,'claude-haiku-5-5','2026-10-30T04:08:46Z',0,0.95,0,'{"areas": ["forecasting"], "confidence": 0.95, "countries": ["JP"], "event_date": "2026-10-29", "institutions": [{"country": "JP", "name": "Japan Meteorological Agency", "short_name": "JMA", "type": "NMHS"}], "language": "ja", "news_type": "other", "original_title": "気象庁1か月予報 北海道は11月上旬にかけて寒い 西日本、東日本は高温傾向 - ウェザーニュース", "primary_area": "forecasting", "relevant": false, "review": false, "summary_en": "JMA issued a one-month forecast covering 31 October to 30 November, indicating cold conditions in Hokkaido into early November and warm tendencies in western and eastern Japan. The item is a conventional seasonal/monthly forecast report with no mention of AI.", "summary_original": "気象庁は10月29日に10月31日から11月30日までの1か月予報を発表し、北海道は11月上旬にかけて寒く、西日本・東日本は高温傾向が続く見込みと報じられています。", "system_name": null, "techniques": [], "title_en": "JMA one-month forecast: Hokkaido cold into early November; western and eastern Japan tend to be warm", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4425,'claude-haiku-5-5','2026-10-30T04:08:38Z',0,0.85,0,'{"areas": ["other"], "confidence": 0.85, "countries": ["JP"], "event_date": "2026-10-29", "institutions": [], "language": "ja", "news_type": "other", "original_title": "中心気圧940hPaの台風31号！AI予測と従来モデルの比較から紐解く警戒すべき3つのポイント - ライブドアニュース", "primary_area": "other", "relevant": false, "review": false, "summary_en": "A Japanese weather forecaster discusses the latest forecast for Typhoon No. 31, including high-wave warnings for the Ogasawara Islands and uncertain approach paths toward mainland Japan. The snippet mentions comparing AI forecasts with conventional models, but it does not describe any AI system being developed or used by an institution, so the item appears to be a media weather report rather than AI operational news.", "summary_original": "気象予報士が台風31号の最新情報を解説し、小笠原諸島の高波警報級のおそれや本州接近時の大雨リスクについて述べています。AI予測と従来モデルの比較に言及がありますが、詳細は示されていません。", "system_name": null, "techniques": [], "title_en": "Typhoon No. 31 with central pressure 940 hPa! Three points to watch from comparing AI forecasts with conventional models - Livedoor News", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4426,'claude-haiku-5-5','2026-10-30T04:08:56Z',0,0.97,0,'{"areas": ["other"], "confidence": 0.97, "countries": ["JP"], "event_date": "2026-10-30", "institutions": [], "language": "ja", "news_type": "other", "original_title": "10月の日本の気温は過去2番目の高さ 各地で遅い真夏日記録を更新｜Infoseekニュース", "primary_area": "other", "relevant": false, "review": false, "summary_en": "A Japanese news item reports that Japan''s October average temperature is about 1.5°C above the baseline, likely the second highest on record after 2024, with late midsummer-day records set in various regions. The snippet mentions no AI, so the item is not relevant to AI in weather operations.", "summary_original": "10月の日本の平均気温は基準値より1.5℃前後高く、2024年に次ぐ過去2番目の高さになるとみられると報じられている。", "system_name": null, "techniques": [], "title_en": "October in Japan Second-Highest Temperature on Record; Late Midsummer-Day Records Updated in Various Regions", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4447,'claude-haiku-5-5','2026-10-30T04:08:54Z',0,0.95,0,'{"areas": ["other"], "confidence": 0.95, "countries": ["ES"], "event_date": "2026-10-29", "institutions": [{"country": "ES", "name": "Institut d''Economia de Barcelona", "short_name": "IEB", "type": "research"}], "language": "es", "news_type": "other", "original_title": "La IA ya empieza a dejar huella en el paro español. Los más expuestos: programadores y diseñadores", "primary_area": "other", "relevant": false, "review": false, "summary_en": "An economic study by the Institut d''Economia de Barcelona examines the impact of AI on employment by occupation in Spain. It concerns labour market effects and does not involve AI applied to weather, water, climate, early warning or disaster risk reduction.", "summary_original": "Un estudio del Institut d''Economia de Barcelona analiza el impacto de la IA en el empleo por ocupación en España, sin relación con meteorología, clima o alerta temprana.", "system_name": null, "techniques": [], "title_en": "AI is starting to leave a mark on Spanish unemployment. Most exposed: programmers and designers", "value_added": null, "value_types": [], "wmo_regions": ["VI"]}');
