INSERT INTO "items" VALUES(2671,'https://www.preventionweb.net/publication/documents-and-publications/when-ocean-comes-inland-tsunami-preparedness-policy-pacific','https://preventionweb.net/publication/documents-and-publications/when-ocean-comes-inland-tsunami-preparedness-policy-pacific','When the ocean comes inland: Tsunami preparedness policy for Pacific island and Hawaii coastal communities — What the warning systems miss','whentheoceancomesinlandtsunamipreparednesspolicyforpacificislandandhawaiicoastalcommunities','preventionweb','PreventionWeb','en','2026-10-23T13:40:14Z','2026-10-24T03:00:26Z','This commentary examines how tsunami warnings translate into evacuation in Pacific Island and Hawaiʻi coastal communities, recommending multilingual alerts, evacuation route analysis, and community-based preparedness programmes.',0.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(2672,'https://www.preventionweb.net/resource/case-study/sri-lanka-managing-landslide-risk-and-planned-relocation-kegalle-district','https://preventionweb.net/resource/case-study/sri-lanka-managing-landslide-risk-and-planned-relocation-kegalle-district','Sri Lanka: Managing landslide risk and planned relocation in Kegalle District','srilankamanaginglandslideriskandplannedrelocationinkegalledistrict','preventionweb','PreventionWeb','en','2026-10-23T13:36:40Z','2026-10-24T03:00:26Z','Around 20 per cent of Sri Lanka’s land is susceptible to landslides. This case study looks at how Kegalle District combines risk mapping, mitigation works, resettlement and community awareness after Cyclone Ditwah displaced thousands.',1.0,'filtered_out',NULL,NULL);
