INSERT INTO "items" VALUES(3677,'https://www.preventionweb.net/drr-community-voices/resilience-starts-home-built-together-lessons-quebec','https://preventionweb.net/drr-community-voices/resilience-starts-home-built-together-lessons-quebec','Resilience starts at home but is built together: Lessons from Québec','resiliencestartsathomebutisbuilttogetherlessonsfromquebec','preventionweb','PreventionWeb','en','2026-10-27T10:37:40Z','2026-10-28T04:00:26Z','As risks evolve and social, environmental, and technical systems grow more interconnected, disaster preparedness extends beyond emergency response. Resilience also depends on the capacities built within homes, neighborhoods, and everyday practices.',1.0,'filtered_out',NULL,NULL);
