INSERT INTO "stories" VALUES(1,'','forecasting','2026-10-17T08:57:14Z','2026-10-17T08:55:25Z','2026-10-09','{"areas": ["observations", "forecasting"], "confidence": 0.6, "countries": [{"code": "KR", "name": "Republic of Korea"}], "event_date": "2026-10-09", "event_name": null, "first_seen": "2026-10-17T08:55:25Z", "id": 1, "institution_types": ["research"], "institutions": [{"country": "KR", "name": "Korea Polar Research Institute", "short_name": "KOPRI", "type": "research"}], "languages": ["en"], "last_updated": "2026-10-17T08:55:25Z", "news_type": "other", "news_types": ["other"], "primary_area": "forecasting", "review": false, "sources": [{"language": "en", "published_at": "2026-10-09T13:26:40Z", "source_name": "Eos (AGU)", "title": "Reliable AI Sea Ice Forecasts Depend on Sustained Observations", "title_en": "Reliable AI Sea Ice Forecasts Depend on Sustained Observations", "url": "https://eos.org/science-updates/reliable-ai-sea-ice-forecasts-depend-on-sustained-observations"}], "summaries_original": {}, "summary_en": "The article argues that AI-based sea ice prediction systems need sustained in-situ observations for validation. It cites an on-ice measurement campaign in the Southern Ocean supported by the Korean icebreaker R/V Araon conducted by KOPRI. The item concerns AI sea ice forecasting, which is a weather/climate-related application, though the snippet is brief.", "system_names": [], "techniques": ["ai_weather_model", "ml_dl"], "title": "Reliable AI Sea Ice Forecasts Depend on Sustained Observations", "value_added": null, "value_types": ["accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(2,'aifs|model_release','forecasting','2026-10-17T08:57:14Z','2026-10-17T08:55:16Z','2026-10-12','{"areas": ["forecasting"], "confidence": 0.95, "countries": [], "event_date": "2026-10-12", "event_name": "AIFS", "first_seen": "2026-10-17T08:55:16Z", "id": 2, "institution_types": ["WMO_centre"], "institutions": [{"country": null, "name": "European Centre for Medium-Range Weather Forecasts", "short_name": "ECMWF", "type": "WMO_centre"}], "languages": ["en"], "last_updated": "2026-10-17T08:55:16Z", "news_type": "model_release", "news_types": ["model_release"], "primary_area": "forecasting", "review": false, "sources": [{"language": "en", "published_at": "2026-10-12T12:00:00Z", "source_name": "ECMWF news", "title": "Bringing the surface ocean into the AIFS", "title_en": "Bringing the surface ocean into the AIFS", "url": "https://www.ecmwf.int/en/about/media-centre/aifs-blog/2026/aifs-marine"}], "summaries_original": {}, "summary_en": "ECMWF announces an extension of its AIFS machine-learning forecasting system that jointly models the atmosphere, ocean waves, sea ice and the surface ocean. The system integrates these components within one ML model, extending AI-based forecasting beyond the atmosphere to marine and ice conditions.", "system_names": ["AIFS"], "techniques": ["ai_weather_model", "ml_dl"], "title": "Bringing the surface ocean into the AIFS", "value_added": "Joint machine-learning model covering the atmosphere, waves, sea ice and the surface ocean in a single system.", "value_types": ["other"], "wmo_regions": []}');
INSERT INTO "stories" VALUES(3,'','operations','2026-10-17T08:57:14Z','2026-10-17T08:55:21Z','2026-10-12','{"areas": ["warnings", "operations", "other"], "confidence": 0.8, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-12", "event_name": null, "first_seen": "2026-10-17T08:55:20Z", "id": 3, "institution_types": ["international", "other_national_agency"], "institutions": [{"country": null, "name": "Office of Digital Evolution and Transformation (UNDRR–ODET initiative)", "short_name": "ODET", "type": "international"}, {"country": null, "name": "United Nations Office for Disaster Risk Reduction", "short_name": "UNDRR", "type": "international"}, {"country": "JP", "name": "Japan International Cooperation Agency", "short_name": "JICA", "type": "other_national_agency"}], "languages": ["en"], "last_updated": "2026-10-17T08:55:21Z", "news_type": "event_conference", "news_types": ["event_conference"], "primary_area": "other", "review": false, "sources": [{"language": "en", "published_at": "2026-10-12T12:52:18Z", "source_name": "UNDRR news", "title": "Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "title_en": "Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "url": "https://www.undrr.org/news/tokyo-workshop-charts-practical-pathways-emerging-technologies-disaster-risk-reduction"}, {"language": "en", "published_at": "2026-10-13T08:03:06Z", "source_name": "ReliefWeb - Updates", "title": "World: Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "title_en": "World: Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "url": "https://reliefweb.int/report/world/tokyo-workshop-charts-practical-pathways-emerging-technologies-disaster-risk-reduction"}], "summaries_original": {}, "summary_en": "UNDRR, with support from the Government of Japan and JICA, convened governments, technology companies, researchers and international organizations in Tokyo on 1-2 October 2026 to discuss how AI and other emerging technologies can become practical disaster risk reduction tools. The workshop focused on pathways from technology to applied use in disaster risk reduction.", "system_names": [], "techniques": ["ml_dl", "other"], "title": "World: Tokyo workshop charts practical pathways for emerging technologies in disaster risk reduction", "value_added": "Explores how artificial intelligence and other emerging technologies can be translated into practical tools for reducing disaster risk.", "value_types": ["other"], "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(4,'','warnings','2026-10-17T08:57:14Z','2026-10-17T08:55:31Z','2026-10-13','{"areas": ["warnings", "operations"], "confidence": 0.6, "countries": [{"code": "ES", "name": "Spain"}], "event_date": "2026-10-13", "event_name": null, "first_seen": "2026-10-17T08:55:31Z", "id": 4, "institution_types": ["NMHS"], "institutions": [{"country": "ES", "name": "Agencia Estatal de Meteorología", "short_name": "AEMET", "type": "NMHS"}], "languages": ["es"], "last_updated": "2026-10-17T08:55:31Z", "news_type": "event_conference", "news_types": ["event_conference"], "primary_area": "warnings", "review": false, "sources": [{"language": "es", "published_at": "2026-10-13T00:00:00Z", "source_name": "AEMET noticias", "title": "Hugo Morán defiende la cooperación iberoamericana para mejorar la prevención de ...", "title_en": "Hugo Morán defends Ibero-American cooperation to improve disaster prevention", "url": "https://www.aemet.es/es/noticias/2026/10/reunion_CODIA_CIMHET"}], "summaries_original": {"es": "En una reunión en Madrid de responsables de agua, meteorología y protección civil, presidida por el presidente de AEMET, se destacó compartir capacidades técnicas, reforzar los sistemas de alerta temprana y aprovechar la inteligencia artificial para anticipar sequías, inundaciones y otros fenómenos extremos."}, "summary_en": "At a meeting in Madrid of water, meteorology and civil protection leaders chaired by the president of AEMET, participants stressed sharing technical capacities, strengthening early warning systems and using artificial intelligence to anticipate droughts, floods and other extreme events. AI is mentioned as a future-oriented opportunity rather than a specific deployed system.", "system_names": [], "techniques": ["ml_dl"], "title": "Hugo Morán defends Ibero-American cooperation to improve disaster prevention", "value_added": null, "value_types": ["other"], "wmo_regions": ["VI"]}');
