INSERT INTO "stories" VALUES(28,'deepmind weather model hurricane track model|other','forecasting','2026-10-25T04:07:35Z','2026-10-25T04:07:23Z','2026-10-24','{"areas": ["forecasting"], "confidence": 0.9, "countries": [], "event_date": "2026-10-24", "event_name": "DeepMind weather model (hurricane track model)", "first_seen": "2026-10-25T04:07:23Z", "id": 28, "institution_types": ["private_sector"], "institutions": [{"country": null, "name": "Google DeepMind", "short_name": "DeepMind", "type": "private_sector"}], "languages": ["es"], "last_updated": "2026-10-25T04:07:23Z", "news_type": "other", "news_types": ["other"], "primary_area": "forecasting", "review": false, "sources": [{"language": "es", "published_at": "2026-10-24T16:30:10Z", "source_name": "Xataka", "title": "La IA ya está cambiando la predicción del tiempo: con el huracán Isaías acertó su trayectoria cuando los modelos tradicionales fallaron", "title_en": "AI is already changing weather forecasting: with Hurricane Isaias it got the track right when traditional models failed", "url": "https://www.xataka.com/ecologia-y-naturaleza/ia-esta-cambiando-prediccion-tiempo-huracan-isaias-acerto-su-trayectoria-cuando-modelos-tradicionales-fallaron"}], "summaries_original": {"es": "Un artículo de Xataka informa de que un modelo meteorológico de machine learning de Google DeepMind acertó la trayectoria del huracán Isaías cuando fallaron los modelos tradicionales, según compartió un usuario en X. El texto señala que estos modelos ya operan en tiempo real para apoyar a los meteorólogos."}, "summary_en": "A Xataka article reports that a machine-learning weather model from Google DeepMind correctly forecast the track of Hurricane Isaias when traditional numerical models failed, as shared by a user on X. The piece frames machine learning models as now operating in real time to support meteorologists.", "system_names": ["DeepMind weather model (hurricane track model)"], "techniques": ["ai_weather_model", "ml_dl"], "title": "AI is already changing weather forecasting: with Hurricane Isaias it got the track right when traditional models failed", "value_added": "Correctly predicted the track of Hurricane Isaias when traditional physics-based models failed.", "value_types": ["accuracy"], "wmo_regions": []}');
INSERT INTO "stories" VALUES(29,'','forecasting','2026-10-26T04:10:37Z','2026-10-26T04:09:22Z','2026-10-21','{"areas": ["forecasting"], "confidence": 0.85, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-21", "event_name": null, "first_seen": "2026-10-26T04:09:22Z", "id": 29, "institution_types": ["private_sector"], "institutions": [{"country": "JP", "name": "Japan Meteorological Corporation (tenki.jp)", "short_name": "tenki.jp", "type": "private_sector"}], "languages": ["ja"], "last_updated": "2026-10-26T04:09:22Z", "news_type": "other", "news_types": ["other"], "primary_area": "forecasting", "review": false, "sources": [{"language": "ja", "published_at": "2026-10-21T04:09:15Z", "source_name": "tenki.jp", "title": "台風30号の進路予想で試される従来予想モデルとAIの実力 欧米ではすでにAI予想も 日本は未導入(放送局のニュース ) - 日本気象協会 tenki.jp", "title_en": "Traditional forecast models vs. AI in predicting the path of Typhoon No. 30; European and US agencies already run AI forecasts, Japan has not yet introduced them (broadcast news)", "url": "https://tenki.jp/news/fnn/f22a0f85-60dc-42cf-9aca-a674f1b9da87.html"}], "summaries_original": {"ja": "欧米の気象機関はAIを使った気象予報モデルを運用しており、2026年に日本に来た台風の予想進路では従来モデルよりAIの方が比較的好成績との評価がある。日本はまだAI予報を導入していないと報じられている。"}, "summary_en": "A news report notes that European and US meteorological agencies already operate AI-based weather forecasting models, and that for a 2026 typhoon approaching Japan, AI track forecasts were rated comparatively better than conventional models. Japan has not yet introduced AI forecasting into operations, according to the report.", "system_names": [], "techniques": ["ai_weather_model"], "title": "Traditional forecast models vs. AI in predicting the path of Typhoon No. 30; European and US agencies already run AI forecasts, Japan has not yet introduced them (broadcast news)", "value_added": "AI forecast models were reported to perform comparatively better than conventional models for the predicted track of a typhoon that approached Japan in 2026.", "value_types": ["accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(30,'','forecasting','2026-10-26T04:10:37Z','2026-10-26T04:10:09Z','2026-10-26','{"areas": ["forecasting"], "confidence": 0.93, "countries": [], "event_date": "2026-10-26", "event_name": null, "first_seen": "2026-10-26T04:10:09Z", "id": 30, "institution_types": ["private_sector"], "institutions": [{"country": null, "name": "Google DeepMind", "short_name": "Google DeepMind", "type": "private_sector"}], "languages": ["es"], "last_updated": "2026-10-26T04:10:09Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "forecasting", "review": false, "sources": [{"language": "es", "published_at": "2026-10-26T04:10:04Z", "source_name": "es.gizmodo.com", "title": "La inteligencia artificial logró predecir la trayectoria de un huracán mejor que los modelos tradicionales: así está cambiando la meteorología", "title_en": "Artificial intelligence managed to predict a hurricane''s trajectory better than traditional models: this is how meteorology is changing", "url": "https://es.gizmodo.com/la-inteligencia-artificial-logro-predecir-la-trayectoria-de-un-huracan-mejor-que-los-modelos-tradicionales-asi-esta-cambiando-la-meteorologia-2000267125"}], "summaries_original": {"es": "Un modelo de inteligencia artificial de Google DeepMind anticipó con notable precisión dónde tocaría tierra el huracán Isaías, con un margen de error de pocas horas cuando faltaban tres días."}, "summary_en": "An AI model from Google DeepMind reportedly predicted where Hurricane Isaias would make landfall more accurately than traditional models, with timing errors of only a few hours three days before impact. The item highlights AI''s growing role in tropical cyclone track forecasting.", "system_names": [], "techniques": ["ai_weather_model"], "title": "Artificial intelligence managed to predict a hurricane''s trajectory better than traditional models: this is how meteorology is changing", "value_added": "Anticipated the landfall location and timing of Hurricane Isaias with a margin of error of a few hours three days ahead, outperforming traditional models as stated in the article.", "value_types": ["accuracy", "lead_time"], "wmo_regions": []}');
INSERT INTO "stories" VALUES(31,'','climate_services','2026-10-27T04:07:49Z','2026-10-27T04:00:49Z','2026-10-25','{"areas": ["climate_services"], "confidence": 0.85, "countries": [{"code": "IN", "name": "India"}], "event_date": "2026-10-25", "event_name": null, "first_seen": "2026-10-27T04:00:49Z", "id": 31, "institution_types": [], "institutions": [], "languages": ["en"], "last_updated": "2026-10-27T04:00:49Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "climate_services", "review": false, "sources": [{"language": "en", "published_at": "2026-10-25T08:15:00Z", "source_name": "kashmirlife.net", "title": "Simple Weather Patterns Better at Predicting Sunshine in Jammu and Kashmir Than Complex AI Models: Study", "title_en": "Simple Weather Patterns Better at Predicting Sunshine in Jammu and Kashmir Than Complex AI Models: Study", "url": "https://kashmirlife.net/simple-weather-patterns-better-at-predicting-sunshine-in-jammu-and-kashmir-than-complex-ai-models-study-458166/"}], "summaries_original": {}, "summary_en": "A 2026 study reported that simple linear regression predicts sunshine duration in Jammu and Kashmir more accurately than complex machine-learning models. The findings challenge the assumption that advanced algorithms always produce better climate estimates. The item is relevant because it compares ML approaches for climate-related estimation, though no operational institution is named.", "system_names": [], "techniques": ["ml_dl"], "title": "Simple Weather Patterns Better at Predicting Sunshine in Jammu and Kashmir Than Complex AI Models: Study", "value_added": "Simple linear regression predicted sunshine duration more accurately than complex machine-learning models in the study.", "value_types": ["accuracy"], "wmo_regions": ["II"]}');
