INSERT INTO "stories" VALUES(33,'','operations','2026-10-27T04:07:54Z','2026-10-27T04:01:07Z','2026-10-26','{"areas": ["communication", "operations"], "confidence": 0.85, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-26", "event_name": null, "first_seen": "2026-10-27T04:01:07Z", "id": 33, "institution_types": ["private_sector"], "institutions": [{"country": "JP", "name": "Weathernews Inc.", "short_name": "Weathernews", "type": "private_sector"}], "languages": ["ja"], "last_updated": "2026-10-27T04:01:07Z", "news_type": "policy_guidance", "news_types": ["policy_guidance"], "primary_area": "operations", "review": false, "sources": [{"language": "ja", "published_at": "2026-10-26T22:00:00Z", "source_name": "日経クロステック", "title": "AI全振りで気象サービス変革 民間だからこそAIネーティブ化推進", "title_en": "Weather service transformation fully powered by AI; AI-native promotion as a private company", "url": "https://xtech.nikkei.com/atcl/nxt/mag/nc/18/020600001/102000220/"}], "summaries_original": {"ja": "過去最高売上高を17期連続で更新し、営業利益率も21％超となるなど好調な同社を牽引する。全プロダクトへのAIエージェント投入など「AI Fusion Company」への転換を掲げ、人の能力とAIを融合させた「融合型の気象プロフェッショナル集団」を目指す。"}, "summary_en": "Japanese private weather company Weathernews reports record sales for 17 consecutive periods and plans to transform into an ''AI Fusion Company'' by deploying AI agents across all its products. The strategy aims to build a hybrid team of meteorological professionals combining human expertise with AI. The article focuses on corporate strategy rather than a specific AI weather model.", "system_names": [], "techniques": ["llm_genai"], "title": "Weather service transformation fully powered by AI; AI-native promotion as a private company", "value_added": "Company transformation into an ''AI Fusion Company'' combining human meteorologists with AI agents across all products, aiming to boost business performance.", "value_types": ["efficiency", "other"], "wmo_regions": ["II"]}');
