INSERT INTO "stories" VALUES(35,'mlcf machine learning classification framework|pilot_research','other','2026-10-28T04:06:44Z','2026-10-28T04:00:26Z','2026-10-27','{"areas": ["other"], "confidence": 0.8, "countries": [], "event_date": "2026-10-27", "event_name": "MLCF (machine-learning classification framework)", "first_seen": "2026-10-28T04:00:26Z", "id": 35, "institution_types": [], "institutions": [], "languages": ["en"], "last_updated": "2026-10-28T04:00:26Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "other", "review": false, "sources": [{"language": "en", "published_at": "2026-10-27T14:54:50Z", "source_name": "PreventionWeb", "title": "Event-level attribution of wildfire ignitions using a machine-learning framework", "title_en": "Event-level attribution of wildfire ignitions using a machine-learning framework", "url": "https://www.preventionweb.net/publication/documents-and-publications/event-level-attribution-wildfire-ignitions-using-machine"}], "summaries_original": {}, "summary_en": "A study introduces a machine-learning classification framework (MLCF) that attributes the cause of wildfire ignitions as either human- or lightning-induced at a global, event-level scale. The work is research-oriented and relevant to disaster risk reduction and wildfire management, though it does not specify an operational NMHS or early warning agency deployment.", "system_names": ["MLCF (machine-learning classification framework)"], "techniques": ["ml_dl"], "title": "Event-level attribution of wildfire ignitions using a machine-learning framework", "value_added": "Attributes wildfire ignition cause (human vs lightning) at global event level, supporting wildfire risk and disaster management understanding.", "value_types": ["accuracy", "coverage"], "wmo_regions": []}');
INSERT INTO "stories" VALUES(36,'','forecasting','2026-10-28T04:06:45Z','2026-10-28T04:01:30Z','2026-10-27','{"areas": ["observations", "forecasting", "warnings"], "confidence": 0.8, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-10-27", "event_name": null, "first_seen": "2026-10-28T04:01:30Z", "id": 36, "institution_types": [], "institutions": [], "languages": ["en"], "last_updated": "2026-10-28T04:01:30Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "forecasting", "review": false, "sources": [{"language": "en", "published_at": "2026-10-27T21:50:01Z", "source_name": "Phys.org Earth news", "title": "AI and satellite data could give Florida earlier warnings of toxic red tides", "title_en": "AI and satellite data could give Florida earlier warnings of toxic red tides", "url": "https://phys.org/news/2026-10-ai-satellite-florida-earlier-toxic.html"}], "summaries_original": {}, "summary_en": "Research reported by Phys.org suggests that AI applied to satellite data could give Florida earlier warnings of toxic red tide algal blooms, which harm respiratory health, fish and coastal neurological health. The article covers a research approach rather than an operational system, and the snippet does not name specific institutions or models.", "system_names": [], "techniques": ["ml_dl"], "title": "AI and satellite data could give Florida earlier warnings of toxic red tides", "value_added": "Earlier warnings of toxic red tide blooms by combining AI with satellite data.", "value_types": ["accuracy", "lead_time"], "wmo_regions": ["IV"]}');
INSERT INTO "stories" VALUES(37,'','forecasting','2026-10-28T04:06:46Z','2026-10-28T04:02:04Z','2026-10-28','{"areas": ["forecasting"], "confidence": 0.85, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-10-28", "event_name": null, "first_seen": "2026-10-28T04:02:04Z", "id": 37, "institution_types": ["other"], "institutions": [{"country": "JP", "name": "UMK テレビ宮崎", "short_name": "UMK", "type": "other"}], "languages": ["ja"], "last_updated": "2026-10-28T04:02:04Z", "news_type": "other", "news_types": ["other"], "primary_area": "forecasting", "review": false, "sources": [{"language": "ja", "published_at": "2026-10-28T04:01:59Z", "source_name": "umk.co.jp", "title": "台風30号「AI予測」が勝った!? 従来予測とAI予測の違いを気象予報士が解説｜関連記事｜古山さんのお天気ポケット｜UMKテレビ宮崎", "title_en": "Typhoon No. 30 \"AI forecast\" wins? Weather forecaster explains differences between conventional and AI forecasts", "url": "https://www.umk.co.jp/news/tenki/2026/10/30aiai.html"}], "summaries_original": {"ja": "台風30号では、18日の時点でAIが九州に向かうルートを早い段階から示し、19日にはより強い確信で九州方面へ更新したと解説されている。従来モデルの多くは大陸方面を予測していた。"}, "summary_en": "A Japanese regional TV station (UMK) explains that for Typhoon No. 30, AI forecasts showed a track toward Kyushu from 18 October and updated with greater confidence on 19 October, whereas many conventional models predicted a path toward the continent. The article is a media explanation of AI typhoon track forecasting performance rather than an institutional deployment.", "system_names": [], "techniques": ["ai_weather_model"], "title": "Typhoon No. 30 \"AI forecast\" wins? Weather forecaster explains differences between conventional and AI forecasts", "value_added": "AI forecasts indicated a track toward Kyushu earlier and with more confidence than many conventional models, which predicted the continental direction.", "value_types": ["accuracy", "lead_time"], "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(38,'','forecasting','2026-10-29T04:10:09Z','2026-10-29T04:01:00Z','2026-10-28','{"areas": ["forecasting", "warnings"], "confidence": 0.85, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-10-28", "event_name": null, "first_seen": "2026-10-29T04:01:00Z", "id": 38, "institution_types": ["research"], "institutions": [{"country": "US", "name": "NYU Fire Research Group", "short_name": "NYU Fire Research Group", "type": "research"}], "languages": ["en"], "last_updated": "2026-10-29T04:01:00Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "forecasting", "review": false, "sources": [{"language": "en", "published_at": "2026-10-28T20:00:10Z", "source_name": "Phys.org Earth news", "title": "A new physics-informed AI tool aims to predict wildfire spread in real time and assist wildfire response", "title_en": "A new physics-informed AI tool aims to predict wildfire spread in real time and assist wildfire response", "url": "https://phys.org/news/2026-10-physics-ai-tool-aims-wildfire.html"}], "summaries_original": {}, "summary_en": "The NYU Fire Research Group has developed a physics-informed AI system described as a digital twin of an active wildfire. In early testing it showed the ability to forecast fire spread in near real time, with the aim of assisting wildfire response.", "system_names": [], "techniques": ["ml_dl"], "title": "A new physics-informed AI tool aims to predict wildfire spread in real time and assist wildfire response", "value_added": "Forecasts how a wildfire will spread in near real time, as a digital twin of an active fire, to assist wildfire response.", "value_types": ["lead_time", "speed"], "wmo_regions": ["IV"]}');
